reak;case 405:name="[Skill 2] Récupération";break;case 406:name="[Skill 3] Récupération";break;case 407:name="[Skill 1] Précision";break;case 408:name="[Skill 2] Précision";break;case 409:name="[Skill 3] Précision";break;case 410:name="[Skill 3/4] Dégâts CRIT";break;case 411:name="Première attaque : dégâts CRIT";break;default:name="Effet #"+id;break;}return (effect.Length>3&&I(effect[3])!=0?"↻ ":"")+name+"  +"+F(effect[1]).ToString("0.##")+(effect.Length>2&&F(effect[2])>0?"  ["+F(effect[2]).ToString("0")+"]":"");}
