    static string StackStats(string s){
      if(string.IsNullOrWhiteSpace(s)||s.IndexOf("pas de donnée",StringComparison.OrdinalIgnoreCase)>=0)return s;
      return string.Join("\r\n",s.Replace(" • ","\n").Replace(" / ","\n").Replace(", ","\n").Split('\n').Select(x=>x.Trim()).Where(x=>x.Length>0).ToArray());
    }
    static string FormatSlotMains(string s){
      if(string.IsNullOrWhiteSpace(s)||s=="—")return s;
      return string.Join("\r\n",s.Split(new[]{" • "},StringSplitOptions.RemoveEmptyEntries).Select(part=>{
        string x=part.Trim();
        if(x.StartsWith("S2",StringComparison.OrdinalIgnoreCase)&& (x.Length==2||x[2]==' '))x="SLOT 2"+x.Substring(2);
        else if(x.StartsWith("S4",StringComparison.OrdinalIgnoreCase)&&(x.Length==2||x[2]==' '))x="SLOT 4"+x.Substring(2);
        else if(x.StartsWith("S6",StringComparison.OrdinalIgnoreCase)&&(x.Length==2||x[2]==' '))x="SLOT 6"+x.Substring(2);
        return x;
      }).Where(x=>x.Length>0).ToArray());
    }
