        public Info Art(string elemMain,string elemSubs,string typeMain,string typeSubs){ElemMain=elemMain;ElemSubs=elemSubs;TypeMain=typeMain;TypeSubs=typeSubs;return this;}
        public string ElemText(){return ElemMain==null?null:ElemMain+" — subs: "+ElemSubs;}
