      static Info M(string combos,string focus){var info=new Info{Focus=focus.Split(',')};foreach(var part in combos.Split(',')){var kv=part.Split(':');if(kv.Length==2)info.Combos.Add(new Combo{Name=kv[0],Pct=F(kv[1])});}return info;}
      static readonly Dictionary<string,Info> FileByName=new Dictionary<string,Info>(StringComparer.OrdinalIgnoreCase);
      static readonly Dictionary<int,Info> FileById=new Dictionary<int,Info>();
      static bool fileTried;
      static string Nz(string s){return string.IsNullOrWhiteSpace(s)?null:s;}
      public static void Reload(string catalogPath){fileTried=false;FileByName.Clear();FileById.Clear();EnsureLoaded(catalogPath);}
      public static void EnsureLoaded(string catalogPath){
        if(fileTried)return;fileTried=true;
        try{
          string dir=string.IsNullOrEmpty(catalogPath)?null:Path.GetDirectoryName(catalogPath);
          string p=dir==null?null:Path.GetFullPath(Path.Combine(dir,"..","rta","rta-meta-top300.json"));
          if(string.IsNullOrEmpty(p)||!File.Exists(p))p=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","rta","rta-meta-top300.json");
          if(!File.Exists(p))return;
          var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=128};
          var root=D(js.DeserializeObject(File.ReadAllText(p)));
          foreach(var raw in Ar(G(root,"monsters"))){
            var d=D(raw);if(d==null)continue;
            int id=I(G(d,"id"));string name=Convert.ToString(G(d,"name")??"");
            var info=new Info{Focus=new string[0],SlotMains=Nz(Convert.ToString(G(d,"slot_mains")??"")),SynergyText=Nz(Convert.ToString(G(d,"synergy_text")??""))};
            foreach(var s in Ar(G(d,"synergy"))){
              var sd=D(s);if(sd==null)continue;
              int sid=I(G(sd,"id"));int cnt=I(G(sd,"count"));string sn=Convert.ToString(G(sd,"name")??"");
              if(sid>0)info.Synergy[sid]=cnt;
              if(!string.IsNullOrEmpty(sn))info.SynergyByName[sn]=cnt;
            }
            foreach(var c in Ar(G(d,"sets"))){var cd=D(c);if(cd==null)continue;string cn=Convert.ToString(G(cd,"name")??"");if(cn.Length==0)continue;info.Combos.Add(new Combo{Name=cn,Pct=F(G(cd,"pct"))});}
            var focus=new List<string>();var subs=new List<string>();
            foreach(var s in Ar(G(d,"focus"))){string n=Convert.ToString(s??"");if(n.Length>0&&!focus.Contains(n))focus.Add(n);}
            foreach(var s in Ar(G(d,"subs"))){var sd=D(s);if(sd==null)continue;string n=Convert.ToString(G(sd,"name")??"");if(n.Length==0)continue;double pct=F(G(sd,"pct"));subs.Add(n+" "+pct.ToString("0.#",CultureInfo.InvariantCulture)+"%");if(!focus.Contains(n))focus.Add(n);}
            if(focus.Count>0)info.Focus=focus.Take(4).ToArray();
            info.SubsText=subs.Count>0?string.Join(", ",subs.Take(5)):null;
            info.Art(Nz(Convert.ToString(G(d,"art_elem_main")??"")),Nz(Convert.ToString(G(d,"art_elem_subs")??"")),Nz(Convert.ToString(G(d,"art_type_main")??"")),Nz(Convert.ToString(G(d,"art_type_subs")??"")));
            if(id>0)FileById[id]=info;
            if(name.Length>0)FileByName[name]=info;
          }
        }catch{}
      }
      public static Info ForId(int id){Info info;return id>0&&FileById.TryGetValue(id,out info)?info:null;}
      public static int SynCount(int aId,string aName,int bId,string bName){
        int n=0;
        n=Math.Max(n,SynHit(ForId(aId)??For(aName),bId,bName));
        n=Math.Max(n,SynHit(ForId(bId)??For(bName),aId,aName));
        return n;
      }
      static int SynHit(Info info,int id,string name){
        if(info==null)return 0;int n=0,v;
        if(id>0&&info.Synergy.TryGetValue(id,out v))n=Math.Max(n,v);
        if(!string.IsNullOrEmpty(name)&&info.SynergyByName.TryGetValue(name.Trim(),out v))n=Math.Max(n,v);
        return n;
      }
