      static string StripAccents(string s){if(string.IsNullOrEmpty(s))return s;var norm=s.Normalize(System.Text.NormalizationForm.FormD);var sb=new System.Text.StringBuilder();foreach(var c in norm)if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark)sb.Append(c);return sb.ToString().Normalize(System.Text.NormalizationForm.FormC);}
      public static Info For(string name){if(string.IsNullOrEmpty(name))return null;Info info;if(FileByName.TryGetValue(name,out info))return info;if(Table.TryGetValue(name,out info))return info;foreach(var kv in FileByName)if(name.IndexOf(kv.Key,StringComparison.OrdinalIgnoreCase)>=0)return kv.Value;foreach(var kv in Table)if(name.IndexOf(kv.Key,StringComparison.OrdinalIgnoreCase)>=0)return kv.Value;
        var stripped=StripAccents(name);
        foreach(var kv in FileByName)if(string.Equals(StripAccents(kv.Key),stripped,StringComparison.OrdinalIgnoreCase))return kv.Value;
        if(!string.Equals(stripped,name,StringComparison.Ordinal)){foreach(var kv in Table)if(string.Equals(StripAccents(kv.Key),stripped,StringComparison.OrdinalIgnoreCase))return kv.Value;foreach(var kv in Table)if(stripped.IndexOf(StripAccents(kv.Key),StringComparison.OrdinalIgnoreCase)>=0)return kv.Value;}
        else{foreach(var kv in Table)if(string.Equals(StripAccents(kv.Key),stripped,StringComparison.OrdinalIgnoreCase))return kv.Value;}
        return null;}
    }
    public static List<RtaBuildRow> BuildForTest(string json,string catalog,List<RtaMonster> meta){return Build(json,catalog,meta,id=>null,20);}
    static List<RtaBuildRow> Build(string json,string catalog,List<RtaMonster> meta,Func<int,Image> icon,int poolSize){RtaMetaBuilds.EnsureLoaded(catalog);var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=D(js.DeserializeObject(Read(json)));var names=new Dictionary<int,string>();var catalogGroups=new Dictionary<int,int>();var catalogElements=new Dictionary<int,string>();foreach(var x in Ar(js.DeserializeObject(File.ReadAllText(catalog)))){var d=D(x);int id=I(G(d,"id"));if(id>0){names[id]=Convert.ToString(G(d,"name","Monstre "+id));catalogGroups[id]=I(G(d,"skillgroup"));catalogElements[id]=Convert.ToString(G(d,"element"));}}var metaBy=meta.Where(x=>x.Id>0).GroupBy(x=>x.Id).ToDictionary(g=>g.Key,g=>g.OrderByDescending(x=>x.Played).First());var resolvedMetaByMaster=new Dictionary<int,RtaMonster>();var units=new List<U>();foreach(var x in Ar(G(root,"unit_list"))){var d=D(x);int m=I(G(d,"unit_master_id"));RtaMonster direct;metaBy.TryGetValue(m,out direct);int group;string element;RtaMonster groupBest=null;if(catalogGroups.TryGetValue(m,out group)&&group>0&&catalogElements.TryGetValue(m,out element))groupBest=metaBy.Values.Where(candidate=>catalogGroups.ContainsKey(candidate.Id)&&catalogGroups[candidate.Id]==group&&catalogElements.ContainsKey(candidate.Id)&&string.Equals(catalogElements[candidate.Id],element,StringComparison.OrdinalIgnoreCase)).OrderByDescending(candidate=>candidate.Played).FirstOrDefault();
      // Un skin collab (ex Megumi Fushiguro) et sa version non-collab possedee (ex Tetsuya)
      // partagent le meme skillgroup+element sur swlens/lucksack : on credite TOUJOURS le jeu de
